<script lang="ts">
let {entity,connections=[]}=$props();let depth=$state(2),showLabels=$state(true),selected=$state<any>(null),scale=$state(1),panX=$state(0),panY=$state(0),dragging=$state(false),dragX=0,dragY=0,startPanX=0,startPanY=0;const W=1280,H=760,cx=640,cy=380;const direct=$derived(connections.slice(0,24));
const second=$derived.by(()=>{const seen=new Set<number>(),out:any[]=[];for(const c of direct)for(const edge of(c.graph_second_hop??[])){const other=Number(edge.subject_id)===Number(c.connected_id)?{id:Number(edge.object_id),name:edge.object_name,type:edge.object_type,rfx:edge.object_gets_rfx_entity_id,supplier:edge.object_gets_supplier_entity_id}:{id:Number(edge.subject_id),name:edge.subject_name,type:edge.subject_type,rfx:edge.subject_gets_rfx_entity_id,supplier:edge.subject_gets_supplier_entity_id};if(other.id===Number(entity.id)||seen.has(Number(edge.id)))continue;seen.add(Number(edge.id));out.push({edge,parent:Number(c.connected_id),parentName:c.connected_name,...other});if(out.length>=60)return out;}return out;});
function parse(v:any){try{return v?JSON.parse(String(v)):{};}catch{return{}}}function clean(v:any){return String(v||'Record').replace(/^Supplier record — /,'').replace(/ — RFx .*$/,'').replace(/^Procurement record RFx [^—]+ — /,'')}function kindDirect(c:any){const m=parse(c.connected_metadata_json);if(c.connected_gets_rfx_entity_id)return'tender';if(c.connected_gets_supplier_entity_id)return'supplier';if(m?.gets?.kind==='agency'||c.connected_type==='public_agency')return'agency';if(String(c.connected_slug??'').startsWith('charities-officer-')||c.connected_type==='person')return'person';return String(c.connected_type||'other')}function kind2(n:any){if(n.rfx)return'tender';if(n.supplier)return'supplier';if(n.type==='public_agency')return'agency';return String(n.type||'other')}function rootKind(){return entity.entity_type==='public_agency'?'agency':entity.entity_type==='person'?'person':String(entity.entity_type||'other')}function fill(k:string){return k==='agency'?'#55c88a':k==='tender'?'#62a9e8':k==='supplier'?'#b984df':k==='charity'?'#e58a58':k==='person'?'#e6c65b':k==='company'?'#83b7ad':'#9aa7a2'}function labelKind(k:string){return k==='agency'?'Government agency':k==='tender'?'Government tender':k==='supplier'?'GETS supplier':k==='person'?'Officer / person':k==='charity'?'Charity':k==='company'?'Company':'Other entity'}function short(s:string,n=34){return s.length>n?s.slice(0,n-1)+'…':s}function directPos(i:number,n:number){const a=i/Math.max(n,1)*Math.PI*2-Math.PI/2,rx=n<=8?300:330,ry=n<=8?235:260;return{x:cx+Math.cos(a)*rx,y:cy+Math.sin(a)*ry}}function secondPos(i:number,n:number){const a=i/Math.max(n,1)*Math.PI*2-Math.PI/2+.045;return{x:cx+Math.cos(a)*535,y:cy+Math.sin(a)*325}}function dpos(id:number){return directPos(Math.max(direct.findIndex((c:any)=>Number(c.connected_id)===id),0),direct.length)}
function selectSecond(n:any,k:string){selected={id:n.id,name:n.name,predicate:n.edge.predicate,kind:k,source:n.edge,parent:n.parent,parentName:n.parentName,level:2,...n.edge}}function selectDirect(c:any,k:string){selected={id:c.connected_id,name:c.connected_name,predicate:c.predicate,kind:k,source:c,level:1,...c}}function keySecond(e:KeyboardEvent,n:any,k:string){if(e.key==='Enter'||e.key===' '){e.preventDefault();selectSecond(n,k)}}function keyDirect(e:KeyboardEvent,c:any,k:string){if(e.key==='Enter'||e.key===' '){e.preventDefault();selectDirect(c,k)}}function fit(){scale=1;panX=0;panY=0}function reset(){depth=2;showLabels=true;selected=null;fit()}function zoomBy(f:number){scale=Math.max(.5,scale*f)}function wheel(e:WheelEvent){e.preventDefault();zoomBy(e.deltaY<0?1.12:1/1.12)}function pointerDown(e:PointerEvent){if((e.target as Element)?.closest?.('.node'))return;dragging=true;dragX=e.clientX;dragY=e.clientY;startPanX=panX;startPanY=panY;(e.currentTarget as Element).setPointerCapture(e.pointerId)}function pointerMove(e:PointerEvent){if(dragging){panX=startPanX+e.clientX-dragX;panY=startPanY+e.clientY-dragY}}function pointerUp(e:PointerEvent){dragging=false;try{(e.currentTarget as Element).releasePointerCapture(e.pointerId)}catch{}}
function list(v:any){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean)}function projectTitle(s:any){return clean(s.graph_rfx_title||s.parentName||s.name)}function agency(s:any){return clean(s.graph_posting_agency||entity.canonical_name)}function supplierTotal(s:any){return Number(s.graph_supplier_count||0)}function projectSentence(s:any){const cats=list(s.graph_categories),regions=list(s.graph_regions),type=String(s.graph_rfx_type||'').trim();let bits=[];if(type)bits.push(`It was published as a ${type}.`);if(cats.length)bits.push(`The source classifies the work as ${cats.slice(0,2).join(' and ')}.`);if(regions.length)bits.push(`The recorded region${regions.length>1?'s are':' is'} ${regions.slice(0,3).join(', ')}${regions.length>3?' and others':''}.`);return bits.join(' ')}
function story(s:any){const title=projectTitle(s),a=agency(s),n=supplierTotal(s);if(s.kind==='supplier'&&s.predicate==='AWARDED_TO')return `${a} selected ${clean(s.name)}${n>1?` as one of ${n} awarded suppliers`:''} for “${title}”.`;if(s.kind==='tender'&&s.predicate==='ISSUED')return `${a} ran a government procurement called “${title}”${n?` and the source records ${n} awarded supplier${n===1?'':'s'}`:''}.`;if(s.predicate==='OFFICER_OF'||s.predicate==='officer_of')return `${clean(s.name)} is recorded in the public source as having an officer relationship.`;return `${clean(s.name)} is connected to ${clean(entity.canonical_name)} through the recorded relationship “${String(s.predicate).replaceAll('_',' ').toLowerCase()}”.`}
function caveat(s:any){if(s.kind==='supplier'&&s.predicate==='AWARDED_TO')return `GETS records this supplier as successful for the procurement. ${/panel/i.test(projectTitle(s))?'Because the tender appears to be a supplier panel, selection does not necessarily mean this supplier was commissioned for a particular job or paid the full reported tender value. ':'This does not by itself prove exactly what work the supplier ultimately performed or how much it was paid. '}NZ Records is describing only what the source evidence establishes.`;if(s.kind==='tender'&&s.predicate==='ISSUED')return 'NZ Records has no detailed project overview stored for this tender, so it will not guess at work that is not described by the source data.';return 'This connection reflects a relationship recorded in a public source. It does not by itself imply wrongdoing, influence or endorsement.'}
</script>
<section class="graph-section"><div class="graph-head"><div><p class="eyebrow">Relationship explorer</p><h2>Graph view</h2></div><div class="head-actions"><span>{direct.length} direct · {second.length} second-hop</span><button onclick={fit}>Fit graph</button><button onclick={reset}>Reset</button></div></div><div class="graph-shell">
<aside class="legend panel"><strong>Legend</strong>{#each [['agency','Government agency'],['tender','Government tender'],['supplier','GETS supplier'],['charity','Charity'],['person','Officer / person'],['company','Company'],['other','Other entity']] as item}<span><i style={`background:${fill(item[0])}`}></i>{item[1]}</span>{/each}<div class="rel-legend"><strong>Relationships</strong><span><b class="line issued"></b>Issued</span><span><b class="line awarded"></b>Awarded to</span><span><b class="line officer"></b>Officer of</span></div></aside>
<div class:dragging class="canvas" onwheel={wheel} onpointerdown={pointerDown} onpointermove={pointerMove} onpointerup={pointerUp} onpointercancel={pointerUp}>{#if !connections.length}<div class="graph-empty">No connections are currently loaded for this record.</div>{:else}<svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`Relationship graph for ${entity.canonical_name}`}><g transform={`translate(${panX} ${panY}) translate(${cx*(1-scale)} ${cy*(1-scale)}) scale(${scale})`}>{#if depth===2}{#each second as n,i}{@const a=dpos(n.parent)}{@const b=secondPos(i,second.length)}<line class:awarded={n.edge.predicate==='AWARDED_TO'} class="second-edge" x1={a.x} y1={a.y} x2={b.x} y2={b.y}/>{/each}{/if}{#each direct as c,i}{@const p=directPos(i,direct.length)}<line class:issued={c.predicate==='ISSUED'} class:awarded={c.predicate==='AWARDED_TO'} class:officer={c.predicate==='OFFICER_OF'||c.predicate==='officer_of'} x1={cx} y1={cy} x2={p.x} y2={p.y}/>{/each}{#if depth===2}{#each second as n,i}{@const p=secondPos(i,second.length)}{@const k=kind2(n)}<g class="node secondary" role="link" tabindex="0" onclick={()=>selectSecond(n,k)} onkeydown={(e)=>keySecond(e,n,k)}><circle class:selected={selected?.id===n.id} cx={p.x} cy={p.y} r="15" fill={fill(k)}/>{#if showLabels}<text class="node-label secondary-label" x={p.x} y={p.y+32} text-anchor="middle">{short(clean(n.name),28)}</text>{/if}</g>{/each}{/if}{#each direct as c,i}{@const p=directPos(i,direct.length)}{@const k=kindDirect(c)}<g class="node" role="link" tabindex="0" onclick={()=>selectDirect(c,k)} onkeydown={(e)=>keyDirect(e,c,k)}><circle class:selected={selected?.id===c.connected_id} cx={p.x} cy={p.y} r="22" fill={fill(k)}/>{#if showLabels}<text class="node-label" x={p.x} y={p.y+43} text-anchor="middle">{short(clean(c.connected_name),32)}</text>{/if}</g>{/each}<g class="center"><circle cx={cx} cy={cy} r="42" fill={fill(rootKind())}/><circle cx={cx} cy={cy} r="54" class="halo"/><text class="root-label" x={cx} y={cy+74} text-anchor="middle">{short(entity.canonical_name,42)}</text><text class="root-type" x={cx} y={cy+96} text-anchor="middle">{labelKind(rootKind())}</text></g></g></svg>{/if}<div class="pan-hint">Drag to pan · Scroll to zoom</div><div class="zoom"><button onclick={()=>zoomBy(1/1.2)}>−</button><span>{Math.round(scale*100)}%</span><button onclick={()=>zoomBy(1.2)}>+</button></div></div>
<aside class="controls panel">{#if selected}<div class="inspector"><div class="inspector-top"><button class="back" onclick={()=>selected=null}>← Back</button><span class="type-dot" style={`background:${fill(selected.kind)}`}></span></div><small>{labelKind(selected.kind)}</small><h3>{clean(selected.name)}</h3><div class="relationship-pill">{String(selected.predicate).replaceAll('_',' ')}</div><h4>In plain English</h4><p class="story">{story(selected)}</p>{#if projectSentence(selected)}<div class="project"><strong>What was this project?</strong><p>{projectSentence(selected)}</p>{#if selected.graph_rfx_title}<p class="source-title">GETS title: “{selected.graph_rfx_title}”</p>{/if}</div>{/if}{#if selected.graph_awarded_amount_raw}<div class="facts"><strong>Source facts</strong><p>Reported / expected value: {selected.graph_awarded_amount_raw}</p></div>{/if}<div class="meaning"><strong>What the evidence tells us</strong><p>{caveat(selected)}</p></div><div class="evidence"><strong>Evidence</strong>{#if selected.source?.publisher}<p>{selected.source.publisher}</p>{/if}{#if selected.source?.dataset}<p>{selected.source.dataset}</p>{/if}</div><div class="inspector-links"><a href={`/record/${selected.id}`}>Open {selected.kind==='tender'?'tender':'record'} →</a>{#if selected.parent}<a href={`/record/${selected.parent}`}>Open tender →</a>{/if}{#if selected.source?.source_url}<a href={selected.source.source_url} target="_blank" rel="noreferrer">View source evidence ↗</a>{/if}</div></div>{:else}<strong>Filters & display</strong><label><span>Depth</span><select bind:value={depth}><option value={1}>1 hop</option><option value={2}>2 hops</option></select></label><label class="check"><input type="checkbox" bind:checked={showLabels}/> Show labels</label><div class="rule"></div><strong>Graph</strong><p><b>{direct.length}</b> directly connected records</p><p><b>{depth===2?second.length:0}</b> second-hop connections</p><p class="help">Click a node to see what the public record says happened, in plain English.</p><button class="reset" onclick={reset}>Reset to defaults</button>{/if}</aside></div><div class="graph-foot"><span>Every connection is based on evidence from a source.</span><span>Centre: <b>{entity.canonical_name}</b> (ID: {entity.id})</span></div><p class="graph-disclaimer"><strong>What does a connection mean?</strong> Lines show relationships found in public records. A connection does not by itself imply wrongdoing, influence or endorsement.</p></section>
<style>
.graph-section{margin-top:38px}.graph-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:12px}.graph-head h2{font-family:Georgia,serif;font-size:32px;margin:2px 0}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#176b5a;font-weight:700;margin:0}.head-actions{display:flex;align-items:center;gap:8px;color:#68726e;font-size:12px}.head-actions button,.reset{border:1px solid #40504c;background:#18211f;color:#e2ebe8;padding:8px 11px;cursor:pointer}.graph-shell{display:grid;grid-template-columns:190px minmax(0,1fr) 285px;min-height:760px;background:#0e1514;border:1px solid #293532;overflow:hidden}.panel{z-index:2;color:#cbd8d3;padding:22px 18px;font-size:12px;background:#101715}.panel>strong,.rel-legend strong{display:block;color:#fff;text-transform:uppercase;letter-spacing:.09em;font-size:10px;margin-bottom:18px}.legend span{display:flex;align-items:center;gap:9px;margin:12px 0}.legend i{width:12px;height:12px;border-radius:50%}.rel-legend{border-top:1px solid #2b3734;margin-top:25px;padding-top:20px}.line{width:23px;border-top:2px solid #70807b}.line.issued{border-color:#62a9e8}.line.awarded{border-color:#b984df}.line.officer{border-color:#e58a58}.canvas{position:relative;min-width:0;overflow:hidden;cursor:grab;touch-action:none;user-select:none;background:radial-gradient(circle at 50% 50%,#1c2a27 0,#111817 58%,#0b1110 100%);border-inline:1px solid #293532}.canvas.dragging{cursor:grabbing}.canvas:before{content:'';position:absolute;inset:0;background-image:radial-gradient(#52635e 1px,transparent 1px);background-size:26px 26px;opacity:.18}.canvas svg{position:relative;width:100%;height:760px}.canvas line{stroke:#657873;stroke-width:2;opacity:.55}.canvas line.issued{stroke:#62a9e8}.canvas line.awarded{stroke:#b984df}.canvas line.officer{stroke:#e58a58}.canvas .second-edge{stroke-width:1.6;opacity:.42}.canvas text{fill:#eef5f2;font-family:Arial,sans-serif;paint-order:stroke;stroke:#0d1412;stroke-width:5px;stroke-linejoin:round;pointer-events:none}.node{cursor:pointer}.node circle{stroke:#f0f6f4;stroke-width:2}.node:hover circle,.node circle.selected{stroke-width:5;filter:drop-shadow(0 0 8px #ffffff55)}.node-label{font-size:16px;font-weight:600}.secondary-label{font-size:13px}.center .halo{fill:none;stroke:#55c88a;stroke-width:3;opacity:.28}.root-label{font-size:20px;font-weight:700}.root-type{font-size:12px;fill:#a9b8b3}.controls label{display:flex;flex-direction:column;gap:8px;margin:15px 0}.controls select{background:#192320;border:1px solid #40504c;color:#e5eeeb;padding:9px}.controls .check{flex-direction:row}.controls p{line-height:1.55;color:#a7b4b0}.controls p b{color:#fff}.rule{border-top:1px solid #2b3734;margin:22px 0}.reset{width:100%;margin-top:18px}.inspector-top{display:flex;justify-content:space-between;margin-bottom:18px}.back{border:0;background:none;color:#9fb0aa;padding:0;cursor:pointer}.type-dot{width:13px;height:13px;border-radius:50%}.inspector>small{color:#82928d;text-transform:uppercase;font-size:9px}.inspector h3{font-family:Georgia,serif;color:#fff;font-size:19px;line-height:1.2;margin:5px 0 10px}.relationship-pill{display:inline-block;border:1px solid #3b4a46;background:#17211e;padding:5px 7px;font-size:9px;text-transform:uppercase;margin-bottom:20px}.inspector h4{color:#fff;font-size:10px;text-transform:uppercase;letter-spacing:.08em;margin:0 0 8px}.inspector .story{color:#edf4f1;font-size:13px;line-height:1.55;font-weight:600}.project,.meaning,.evidence,.facts{border-top:1px solid #2b3734;margin-top:18px;padding-top:16px}.project strong,.meaning strong,.evidence strong,.facts strong{display:block;color:#fff;text-transform:uppercase;letter-spacing:.08em;font-size:9px;margin-bottom:7px}.source-title{color:#7f8e89!important;font-size:10px!important}.inspector-links{display:flex;flex-direction:column;gap:9px;border-top:1px solid #2b3734;margin-top:18px;padding-top:16px}.inspector-links a{color:#83cdb1;font-size:11px;font-weight:700;text-decoration:none}.zoom{position:absolute;left:16px;bottom:16px;display:flex;align-items:center;background:#111a18;border:1px solid #35433f;color:#dce7e3;z-index:4}.zoom button{width:34px;height:32px;border:0;background:transparent;color:#fff;font-size:20px}.zoom span{min-width:52px;text-align:center;font-size:11px}.pan-hint{position:absolute;right:14px;bottom:18px;color:#7f8e89;font-size:10px}.graph-empty{position:absolute;inset:0;display:grid;place-items:center;color:#93a19c}.graph-foot{display:flex;justify-content:space-between;background:#18211f;color:#9eada8;border:1px solid #293532;border-top:0;padding:10px 14px;font-size:11px}.graph-disclaimer{font-size:12px;line-height:1.5;color:#59635f}.graph-disclaimer strong{color:#202624}@media(max-width:800px){.graph-shell{grid-template-columns:1fr}.legend,.controls{display:none}.canvas{border:0}.canvas svg{height:600px}.graph-foot{flex-direction:column;gap:8px}}
</style>